// Import React and required hooks
import React, { useState } from "react";

// Redux: used for dispatching logout action
import { useDispatch } from "react-redux";

// React Router: used for navigation and linking
import { Link, useNavigate } from "react-router-dom";

// Redux action: clears user data on logout
import { logout } from "../Features/UserSlice";

// Component styling
import "../Styles/Header.css";

const Header = () => {
  // Dispatch Redux actions (e.g., logout)
  const dispatch = useDispatch();

  // Used to navigate to different pages programmatically
  const navigate = useNavigate();

  // User role (student / company) stored in localStorage after login
  // This role controls which navigation links appear
  const [role, setRole] = useState(localStorage.getItem("role"));

  // Handle logout: remove saved data and redirect home
  const handleLogout = () => {
    localStorage.removeItem("loggedUser"); // Delete saved user details
    localStorage.removeItem("role"); // Delete stored role

    dispatch(logout()); // Reset Redux state
    setRole(null); // Clear role state

    navigate("/", { replace: true }); // Redirect to Home
  };

  return (
    <header className="header">
      {/* Website Branding (Logo + Title) */}
      <div className="brand">
        <div className="logo-circle">UL</div>
        <div className="brand-text">
          <span className="brand-main">UTAS</span>
          <span className="brand-accent">Link</span>
        </div>
      </div>

      {/* Navigation links change depending on the logged-in role */}
      <nav className="nav-links">
        {/* Home is visible to all users */}
        <Link to="/">Home</Link>

        {/* ---------------- STUDENT NAVIGATION ---------------- */}
        {role === "student" && (
          <>
            <Link to="/find-job">Find Job</Link>
            <Link to="/student-applications">My Applications</Link>
            <Link to="/student-profile">Profile</Link>

            <button onClick={handleLogout} className="logout-btn">
              Logout
            </button>
          </>
        )}

        {/* ---------------- COMPANY NAVIGATION ---------------- */}
        {role === "company" && (
          <>
            <Link to="/company-profile">Company Profile</Link>
            <Link to="/post-job">Post Job</Link>
            <Link to="/company-jobs">My Jobs</Link>
            <Link to="/applicants-job">Applicants</Link>

            <button onClick={handleLogout} className="logout-btn">
              Logout
            </button>
          </>
        )}
      </nav>
    </header>
  );
};

export default Header;
